 void refreshPayoutHistory(){String base=baseUrl(),session=secureStore.get("licence_session"),worker=betaPrefs.getString("worker_id","");if(historyText==null)return;if(base==null||session==null){historyText.setText("İşlem geçmişi için oturum gerekli");return;}io.submit(()->{try{HttpURLConnection c=openApi(base+"/payouts");c.setRequestProperty("Authorization","License "+session);c.setRequestProperty("X-Install-Id",worker);c.setRequestProperty("X-Worker-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200){JSONArray a=j.optJSONArray("payouts");StringBuilder out=new StringBuilder();if(a!=null)for(int n=0;n<Math.min(5,a.length());n++){JSONObject p=a.optJSONObject(n);if(p!=null)out.append(n==0?"":"\n").append("• ").append(p.optString("amountDisplay","—")).append(" USDT_TEST — ").append(p.optString("status","—"));}String v=out.length()==0?"Henüz doğrulanmış işlem yok":out.toString();runOnUiThread(()->{if(historyText!=null)historyText.setText(v);});}else runOnUiThread(()->historyText.setText("İşlem geçmişi kullanılamıyor"));}catch(Exception e){runOnUiThread(()->{if(historyText!=null)historyText.setText("Bağlantı kurulamadı");});}});}
String baseUrl(){String x=betaPrefs.getString("endpoint",BuildConfig.MARSX_API_BASE_URL).trim().replaceAll("/$","");return x.matches("https://[A-Za-z0-9._:-]+")?x:null;}
 HttpURLConnection openApi(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(7000);c.setRequestMethod("GET");c.setRequestProperty("Accept","application/json");return c;}
 String readApi(HttpURLConnection c,int code)throws Exception{InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)return "{}";StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}return b.toString();}
 void refreshMarsxAccount(){String base=baseUrl(),session=secureStore.get("licence_session"),worker=betaPrefs.getString("worker_id","");if(balance==null)return;if(base==null||session==null){balance.setText("— MARS-X • Oturum gerekli");return;}balance.setText("— MARS-X • Güncelleniyor…");io.submit(()->{try{HttpURLConnection c=openApi(base+"/account");c.setRequestProperty("Authorization","License "+session);c.setRequestProperty("X-Install-Id",worker);c.setRequestProperty("X-Worker-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200){String v=j.optString("availableDisplay","0.000000");runOnUiThread(()->{if(balance!=null)balance.setText(v+" MARS-X");});}else runOnUiThread(()->{if(balance!=null)balance.setText("— MARS-X • Güncellenemedi");});}catch(Exception ignored){runOnUiThread(()->{if(balance!=null)balance.setText("— MARS-X • Çevrimdışı");});}});}
 void refreshReferral(TextView codeView,TextView stats){String base=baseUrl(),session=secureStore.get("auth_session"),worker=betaPrefs.getString("worker_id","");if(base==null||session==null){codeView.setText("Giriş yapınca davet kodu oluşur");stats.setText("Toplam davet: —\nDavet kazancı: —");return;}codeView.setText("Davet bilgisi güncelleniyor…");io.submit(()->{try{HttpURLConnection c=openApi(base+"/auth/me");c.setRequestProperty("Authorization","Bearer "+session);c.setRequestProperty("X-Install-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200&&j.optBoolean("ok")){JSONObject r=j.optJSONObject("referral");if(r!=null){String rc=r.optString("code","");int n=r.optInt("invitedCount",0);long units=r.optLong("rewardUnits",0);String rw=java.math.BigDecimal.valueOf(units,6).toPlainString();betaPrefs.edit().putString("referral_code",rc).putInt("referral_invited",n).putString("referral_reward",rw).apply();runOnUiThread(()->{codeView.setText(rc.isEmpty()?"Kod bekleniyor":rc);stats.setText("Toplam davet: "+n+"\nDavet kazancı: "+rw+" MARS-X");});}else runOnUiThread(()->{codeView.setText("Davet bilgisi kullanılamıyor");stats.setText("Toplam davet: —\nDavet kazancı: —");});}else runOnUiThread(()->{codeView.setText("Davet bilgisi güncellenemedi");stats.setText("Toplam davet: —\nDavet kazancı: —");});}catch(Exception ignored){runOnUiThread(()->{codeView.setText("Davet bilgisi • Çevrimdışı");stats.setText("Toplam davet: —\nDavet kazancı: —");});}});}
void loadHistory(){loadSeries("hist_power",powerHistory);loadSeries("hist_temp",tempHistory);loadSeries("hist_latency",latencyHistory);loadTimeSeries("hist_power_times",powerTimes);loadTimeSeries("hist_temp_times",tempTimes);loadTimeSeries("hist_latency_times",latencyTimes);}
 void loadSeries(String key,ArrayList<Float> out){out.clear();String raw=appPrefs.getString(key,"");if(raw.isEmpty())return;for(String x:raw.split(",")){try{out.add(Float.parseFloat(x));}catch(Exception ignored){}}while(out.size()>96)out.remove(0);}
 void addSample(String key,ArrayList<Float> out,float value){if(Float.isNaN(value)||Float.isInfinite(value)||value<0)return;out.add(value);while(out.size()>96)out.remove(0);StringBuilder b=new StringBuilder();for(Float x:out){if(b.length()>0)b.append(',');b.append(x);}appPrefs.edit().putString(key,b.toString()).apply();}
 void addTimedSample(String key,String timeKey,ArrayList<Float> out,ArrayList<Long> times,float value){if(Float.isNaN(value)||Float.isInfinite(value)||value<0)return;long now=System.currentTimeMillis();out.add(value);times.add(now);while(out.size()>96)out.remove(0);while(times.size()>96)times.remove(0);StringBuilder vb=new StringBuilder(),tb=new StringBuilder();for(Float x:out){if(vb.length()>0)vb.append(',');vb.append(x);}for(Long x:times){if(tb.length()>0)tb.append(',');tb.append(x);}appPrefs.edit().putString(key,vb.toString()).putString(timeKey,tb.toString()).apply();}
 void loadTimeSeries(String key,ArrayList<Long> out){out.clear();String raw=appPrefs.getString(key,"");if(raw.isEmpty())return;for(String x:raw.split(","))try{out.add(Long.parseLong(x));}catch(Exception ignored){}while(out.size()>96)out.remove(0);}
void refreshDevice(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return;int level=i.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(android.os.BatteryManager.EXTRA_SCALE,100),raw=i.getIntExtra(android.os.BatteryManager.EXTRA_TEMPERATURE,-1);int pct=scale>0?Math.round(level*100f/scale):-1;float tc=raw>=0?raw/10f:-1;if(battery!=null)battery.setText("Pil alt limiti %"+appPrefs.getInt("battery_limit",15)+"  •  Cihaz pili "+(pct<0?"—":pct+"%"));int lim=appPrefs.getInt("thermal_limit",43);if(temp!=null)temp.setText(tc<0?lim+"°C sınır":String.format(Locale.getDefault(),"%.1f°C / %d°C",tc,lim));if(tc>=0)addTimedSample("hist_temp","hist_temp_times",tempHistory,tempTimes,tc);}
 String poolAge(long ts){if(ts<=0)return "henüz doğrulanmadı";long sec=Math.max(0,(System.currentTimeMillis()-ts)/1000);if(sec<60)return "az önce";long min=sec/60;if(min<60)return min+" dk önce";long hr=min/60;if(hr<24)return hr+" sa önce";return (hr/24)+" gün önce";}
 void refreshPool(){final String addr=poolPrefs.getString("address","");if(!VrscAddress.valid(addr)){if(power!=null)power.setText("— Sol/s");if(workers!=null)workers.setText("—");if(shares!=null)shares.setText("—");if(network!=null)network.setText("MARS-X sağlayıcı • Yapılandırma bekleniyor");return;}if(network!=null)network.setText("Havuz verisi • Güncelleniyor…");final long t0=System.currentTimeMillis();io.submit(()->{try{LuckPoolClient.Snapshot x=pool.load(addr);long ms=System.currentTimeMillis()-t0;final long verifiedAt=System.currentTimeMillis();appPrefs.edit().putLong("last_pool_success",verifiedAt).apply();runOnUiThread(()->{addTimedSample("hist_power","hist_power_times",powerHistory,powerTimes,(float)x.hashrate);addTimedSample("hist_latency","hist_latency_times",latencyHistory,latencyTimes,(float)ms);if(power!=null)power.setText(String.format(Locale.getDefault(),"%,.2f Sol/s",x.hashrate));if(workers!=null){int n=0;for(LuckPoolClient.Worker w:x.workers)if(w.online)n++;workers.setText(String.valueOf(n));}if(shares!=null)shares.setText(x.shareValue);if(network!=null)network.setText("Sağlayıcı bağlantısı • "+ms+" ms • doğrulandı");});}catch(Exception e){final long last=appPrefs.getLong("last_pool_success",0);runOnUiThread(()->{if(power!=null)power.setText("— Sol/s");if(workers!=null)workers.setText("—");if(shares!=null)shares.setText("—");if(network!=null)network.setText("Havuz verisi • Çevrimdışı • son doğrulama "+poolAge(last));});}});}
 public static class NavIconView extends View{Paint p=new Paint(1);int type;boolean selected;public NavIconView(Context c,int t,boolean sel){super(c);type=t;selected=sel;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),cx=w/2,cy=h/2;p.setColor(selected?ORANGE:Color.rgb(160,164,174));p.setStrokeWidth(Math.max(2,w*.07f));p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);Path q=new Path();if(type==0){q.moveTo(w*.18f,h*.5f);q.lineTo(cx,h*.2f);q.lineTo(w*.82f,h*.5f);q.moveTo(w*.28f,h*.46f);q.lineTo(w*.28f,h*.8f);q.lineTo(w*.72f,h*.8f);q.lineTo(w*.72f,h*.46f);}else if(type==1){q.moveTo(w*.15f,h*.72f);q.lineTo(w*.36f,h*.5f);q.lineTo(w*.53f,h*.61f);q.lineTo(w*.82f,h*.27f);}else if(type==2){c.drawRoundRect(new RectF(w*.18f,h*.28f,w*.82f,h*.75f),w*.1f,w*.1f,p);c.drawLine(w*.18f,h*.42f,w*.82f,h*.42f,p);}else if(type==3){c.drawCircle(w*.38f,h*.38f,w*.14f,p);c.drawCircle(w*.67f,h*.43f,w*.11f,p);q.moveTo(w*.17f,h*.78f);q.quadTo(w*.4f,h*.54f,w*.62f,h*.78f);q.moveTo(w*.55f,h*.73f);q.quadTo(w*.69f,h*.59f,w*.84f,h*.75f);}else{c.drawCircle(cx,cy,w*.19f,p);for(int i=0;i<8;i++){double a=i*Math.PI/4;float x1=cx+(float)Math.cos(a)*w*.27f,y1=cy+(float)Math.sin(a)*w*.27f;float x2=cx+(float)Math.cos(a)*w*.39f,y2=cy+(float)Math.sin(a)*w*.39f;c.drawLine(x1,y1,x2,y2,p);}}c.drawPath(q,p);}} public static class MiniMarkView extends View{Paint p=new Paint(1);public MiniMarkView(Context c){super(c);setContentDescription("MARS-X");}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(ORANGE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(3,w*.08f));c.drawCircle(w/2,h/2,w*.35f,p);p.setStyle(Paint.Style.FILL);Path m=new Path();m.moveTo(w*.2f,h*.72f);m.lineTo(w*.34f,h*.25f);m.lineTo(w*.5f,h*.52f);m.lineTo(w*.66f,h*.25f);m.lineTo(w*.8f,h*.72f);m.lineTo(w*.66f,h*.72f);m.lineTo(w*.61f,h*.49f);m.lineTo(w*.5f,h*.68f);m.lineTo(w*.39f,h*.49f);m.lineTo(w*.34f,h*.72f);m.close();c.drawPath(m,p);}} public static class EmblemView extends View{Paint p=new Paint(1);public EmblemView(Context c){super(c);setContentDescription("MARS-X amblemi");}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);Path m=new Path();m.moveTo(w*.15f,h*.82f);m.lineTo(w*.30f,h*.18f);m.lineTo(w*.50f,h*.57f);m.lineTo(w*.70f,h*.18f);m.lineTo(w*.85f,h*.82f);m.lineTo(w*.68f,h*.82f);m.lineTo(w*.63f,h*.50f);m.lineTo(w*.50f,h*.78f);m.lineTo(w*.37f,h*.50f);m.lineTo(w*.32f,h*.82f);m.close();c.drawPath(m,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(4,w*.018f));RectF r=new RectF(w*.10f,h*.32f,w*.90f,h*.70f);c.save();c.rotate(-14,w/2,h/2);c.drawOval(r,p);c.restore();}} public static class GaugeView extends View{Paint p=new Paint(1);public GaugeView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.62f,r=Math.min(w,h)*.38f;p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(Math.max(16,w*.055f));p.setColor(Color.rgb(55,31,18));RectF a=new RectF(cx-r,cy-r,cx+r,cy+r);c.drawArc(a,150,240,false,p);p.setColor(ORANGE);c.drawArc(a,150,120,false,p);p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);Path bolt=new Path();bolt.moveTo(cx+w*.03f,cy-r*.45f);bolt.lineTo(cx-w*.16f,cy);bolt.lineTo(cx-w*.02f,cy);bolt.lineTo(cx-w*.08f,cy+r*.43f);bolt.lineTo(cx+w*.19f,cy-r*.08f);bolt.lineTo(cx+w*.04f,cy-r*.08f);bolt.close();c.drawPath(bolt,p);p.setTextSize(w*.05f);p.setTextAlign(Paint.Align.CENTER);p.setColor(MUTED);c.drawText("DOĞRULANMIŞ GÜÇ",cx,cy+h*.15f,p);}} public static class MarsView extends View{Paint p=new Paint(1);public MarsView(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.48f,r=Math.min(w,h)*.31f;p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(cx-r*.3f,cy-r*.35f,r*1.4f,new int[]{Color.rgb(255,151,55),Color.rgb(181,54,12),Color.rgb(40,8,5)},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(5,w*.018f));p.setColor(ORANGE);RectF o=new RectF(cx-r*1.35f,cy-r*.45f,cx+r*1.35f,cy+r*.45f);c.save();c.rotate(-18,cx,cy);c.drawOval(o,p);c.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(3,w*.009f));p.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<18;i++){p.setColor(i<12?ORANGE:Color.rgb(55,30,18));float a=(float)Math.toRadians(-210+i*14);float rr=r*1.42f;float x1=cx+(float)Math.cos(a)*rr,y1=cy+(float)Math.sin(a)*rr;float x2=cx+(float)Math.cos(a)*(rr+r*.13f),y2=cy+(float)Math.sin(a)*(rr+r*.13f);c.drawLine(x1,y1,x2,y2,p);}p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(90,0,0,0));c.drawCircle(cx+r*.28f,cy-r*.16f,r*.13f,p);c.drawCircle(cx-r*.25f,cy+r*.2f,r*.09f,p);}}
 public static class EmptyChartView extends View{Paint p=new Paint(1);String label;public EmptyChartView(Context c,String l){super(c);label=l;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStrokeWidth(1);p.setColor(Color.rgb(36,40,45));for(int i=1;i<5;i++)c.drawLine(0,h*i/5,w,h*i/5,p);for(int i=1;i<7;i++)c.drawLine(w*i/7,0,w*i/7,h*.82f,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(MUTED);p.setTextSize(Math.max(13,w*.038f));c.drawText(label,w/2,h*.43f,p);p.setTextSize(Math.max(12,w*.033f));c.drawText("Doğrulanmış veri bekleniyor",w/2,h*.58f,p);}}
 public static class SingleSeriesChartView extends View{Paint p=new Paint(1);List<Float> values;List<Long> times;String period,unit;int color;float touchX=-1;public SingleSeriesChartView(Context c,List<Float>v,List<Long>t,String pr,String u,int co){super(c);values=v;times=t;period=pr;unit=u;color=co;setLayerType(View.LAYER_TYPE_SOFTWARE,null);setContentDescription("Doğrulanmış "+u+" telemetri grafiği");setOnTouchListener((x,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN||e.getAction()==MotionEvent.ACTION_MOVE){touchX=e.getX();invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){touchX=-1;invalidate();return true;}return false;});}long window(){if("Haftalık".equals(period))return 7L*86400000;if("Aylık".equals(period))return 30L*86400000;if("Tümü".equals(period))return Long.MAX_VALUE;return 86400000;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),left=w*.16f,right=w*.96f,top=h*.1f,bottom=h*.72f;int count=Math.min(values.size(),times.size());long cutoff=window()==Long.MAX_VALUE?Long.MIN_VALUE:System.currentTimeMillis()-window();int first=0;while(first<count&&times.get(first)<cutoff)first++;if(count-first<2){empty(c,w,h);return;}float min=Float.MAX_VALUE,max=-Float.MAX_VALUE,sum=0;for(int i=first;i<count;i++){float v=values.get(i);min=Math.min(min,v);max=Math.max(max,v);sum+=v;}float avg=sum/(count-first),range=Math.max(.001f,max-min);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(Color.rgb(46,49,57));p.setTextSize(w*.03f);for(int j=0;j<4;j++){float y=top+(bottom-top)*j/3;c.drawLine(left,y,right,y,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.RIGHT);p.setColor(MUTED);float label=max-range*j/3f;c.drawText(fmt(label),left-w*.025f,y+w*.01f,p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.rgb(38,41,48));}Path q=new Path();p.setColor(color);p.setStrokeWidth(Math.max(5,w*.012f));p.setShadowLayer(12,0,0,color);long tFirst=times.get(first),tLast=times.get(count-1);long tRange=Math.max(1L,tLast-tFirst);for(int i=first;i<count;i++){float x=left+(right-left)*((times.get(i)-tFirst)/(float)tRange);float y=bottom-((values.get(i)-min)/range)*(bottom-top);if(i==first)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);p.clearShadowLayer();p.setStyle(Paint.Style.FILL);p.setTextSize(w*.031f);p.setTextAlign(Paint.Align.LEFT);p.setColor(WHITE);c.drawText("Min "+fmt(min)+" "+unit,left,h*.84f,p);p.setTextAlign(Paint.Align.CENTER);c.drawText("Ort "+fmt(avg)+" "+unit,(left+right)/2,h*.84f,p);p.setTextAlign(Paint.Align.RIGHT);c.drawText("Max "+fmt(max)+" "+unit,right,h*.84f,p);java.text.SimpleDateFormat df=new java.text.SimpleDateFormat("Günlük".equals(period)?"HH:mm":"dd MMM",Locale.getDefault());p.setTextSize(w*.028f);p.setColor(MUTED);p.setTextAlign(Paint.Align.LEFT);c.drawText(df.format(new java.util.Date(times.get(first))),left,h*.96f,p);p.setTextAlign(Paint.Align.RIGHT);c.drawText(df.format(new java.util.Date(times.get(count-1))),right,h*.96f,p);if(touchX>=left&&touchX<=right){long target=tFirst+(long)(((touchX-left)/(right-left))*tRange);int ix=first;long best=Long.MAX_VALUE;for(int i=first;i<count;i++){long d=Math.abs(times.get(i)-target);if(d<best){best=d;ix=i;}}float x=left+(right-left)*((times.get(ix)-tFirst)/(float)tRange);p.setColor(WHITE);p.setStrokeWidth(2);c.drawLine(x,top,x,bottom,p);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(w*.03f);c.drawText(df.format(new java.util.Date(times.get(ix)))+" • "+fmt(values.get(ix))+" "+unit,Math.min(right-w*.2f,Math.max(left+w*.2f,x)),top+h*.07f,p);}}void empty(Canvas c,float w,float h){p.setStyle(Paint.Style.FILL);p.setColor(MUTED);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(w*.04f);c.drawText("Doğrulanmış veri bekleniyor",w/2,h*.48f,p);}String fmt(float v){return v>=1000?String.format(Locale.getDefault(),"%.1fk",v/1000f):String.format(Locale.getDefault(),"%.1f",v);}}
 public static class HistoryChartView extends View{Paint p=new Paint(1);List<Float>[] series=new List[3];List<Long> times,tempTimes,latencyTimes;String period;public HistoryChartView(Context c,List<Float>a,List<Float>b,List<Float>d,List<Long>pt,List<Long>tt,List<Long>lt,String per){super(c);series[0]=a;series[1]=b;series[2]=d;times=pt;tempTimes=tt;latencyTimes=lt;period=per;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(MUTED);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(w*.04f);c.drawText("Ayrıntılı telemetri yukarıdaki bağımsız grafiklerde",w/2,h*.48f,p);c.drawText("gerçek zaman damgalarıyla gösterilir.",w/2,h*.58f,p);}}
